Class Maquina
  Define stock, recaudado, precio As Integer;

  Method Constructor(latas As Integer)
    This.stock <- latas;
    This.recaudado <- 0;
    This.precio <- 3;
  EndMethod

  Method Vender() As Boolean
    If This.stock = 0 Then
      Return False;
    EndIf
    This.stock <- This.stock - 1;
    This.recaudado <- This.recaudado + This.precio;
    Return True;
  EndMethod

  Method Estado() As String
    Return toText(This.stock) + " latas, " + toText(This.recaudado) + " pesos";
  EndMethod
EndClass

Algorithm Kiosco
  Define primera As Maquina <- New Maquina(10);
  Define segunda As Maquina <- New Maquina(10);
  Define numero As Integer;
  Read numero;
  While numero <> 0 Do
    If numero = 1 Then
      If Not primera.Vender() Then
        Write "Máquina 1 sin latas";
      EndIf
    Else
      If Not segunda.Vender() Then
        Write "Máquina 2 sin latas";
      EndIf
    EndIf
    Read numero;
  EndWhile
  Write "Máquina 1: ", primera.Estado();
  Write "Máquina 2: ", segunda.Estado();
EndAlgorithm
